import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const p=JSON.parse('{"title":"Installing the mod","description":"","frontmatter":{"pageId":"players/install","contentRevision":1},"headers":[],"relativePath":"en/players/install.md","filePath":"en/players/install.md"}'),r={name:"en/players/install.md"};function l(n,e,s,d,m,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="installing-the-mod" tabindex="-1">Installing the mod <a class="header-anchor" href="#installing-the-mod" aria-label="Permalink to &quot;Installing the mod&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Download a Rimlink archive from the repository releases. Close RimWorld. Extract it so that the Rimlink directory directly contains About and Assemblies, not another nested Rimlink folder. Install Harmony 3.x separately; release packages do not bundle Harmony.</p><p>Enable Harmony and Rimlink in the game&#39;s mod list, respecting dependencies and server instructions. Restart and verify that <strong>Multiplayer</strong> appears. For load failures, first check versions and directory layout, then inspect the game log. Install the server modpack separately or through its offered downloader.</p><h3 id="install-from-a-release" tabindex="-1">Install from a release <a class="header-anchor" href="#install-from-a-release" aria-label="Permalink to &quot;Install from a release&quot;">​</a></h3><ol><li>Open <a href="https://github.com/Asofwar/rimlink/releases" target="_blank" rel="noreferrer">Rimlink releases</a> and choose the client mod archive for your server version, not the server or source archive.</li><li>Exit RimWorld. In Steam, use <strong>Manage → Browse local files</strong> to locate the game directory. Put the extracted Rimlink folder under its <code>Mods</code> directory: <code>Mods/Rimlink/About/About.xml</code> and <code>Mods/Rimlink/Assemblies</code> must exist. Avoid <code>Mods/Rimlink/Rimlink</code> nesting.</li><li>Install Harmony 3.x (separate mod). Start the game with Steam running if Harmony comes from Workshop. In <strong>Mods</strong>, put Harmony first, then Core and enabled DLC, then dependencies/gameplay mods and Rimlink as required by the server collection.</li><li>Enable Rimlink, apply the list and restart. Verify <strong>Multiplayer</strong> is available in the main menu before connecting.</li><li>Connect to the server and complete its modpack check. Reaching the menu alone does not prove your collection matches.</li></ol><p>If Rimlink is absent from the list, check the folder nesting and About metadata. If it is listed but fails to load, verify RimWorld 1.7, Harmony 3.x and the matching Rimlink release; do not solve an assembly error by copying random DLLs into the mod.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Do not replace DLLs while the game is running. Workshop Harmony may be unavailable without Steam running. Server-delivered mods require redistribution permission.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./../compatibility">Versions and compatibility</a></li><li><a href="./modpacks">Server modpacks</a></li><li><a href="./troubleshooting">Player troubleshooting</a></li></ul>',12)])])}const u=a(r,[["render",l]]);export{p as __pageData,u as default};
